SET LOCAL search_path = "metadata", pg_catalog;
CREATE TABLE operation_ledger(actor text NOT NULL,action text NOT NULL,nonce text NOT NULL,envelope_digest text NOT NULL,body_digest text NOT NULL,request_id uuid NOT NULL,response bytea NOT NULL,response_digest text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),retain_until timestamptz NOT NULL DEFAULT clock_timestamp()+interval '24 hours',PRIMARY KEY(actor,action,nonce),CHECK(retain_until>=created_at+interval '24 hours'));
CREATE TABLE security_audit_outbox(id bigserial PRIMARY KEY,request_id uuid NOT NULL,actor_pseudonym text NOT NULL,action text NOT NULL,result text NOT NULL,policy_version text NOT NULL,request_digest text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(request_id,action));